// Gera persona dinâmica para o agente simulador
// Saída: { audiencia, perfil, persona_json, cenario, objetivo, pushName }

const cfg = $input.first().json;

const audReq = (cfg.audiencia_alvo || 'aleatorio').toLowerCase();
const perfReq = (cfg.perfil_cliente || 'aleatorio').toLowerCase();

const pick = (arr) => arr[Math.floor(Math.random() * arr.length)];

const audiencia = audReq === 'aleatorio' ? pick(['b2b', 'b2c']) : audReq;
const perfil = perfReq === 'aleatorio'
  ? pick(['facil', 'dificil', 'confuso', 'fora_cobertura'])
  : perfReq;

// Bancos de personas
const nomesB2C = ['Mariana Souza', 'Pedro Almeida', 'Camila Ribeiro', 'Felipe Santos',
                  'Juliana Costa', 'Rodrigo Lima', 'Beatriz Oliveira', 'Lucas Ferreira'];
const nomesB2B = ['Arq. Renata Cardoso', 'Arq. Gabriel Moreira', 'Designer Patricia Mendes',
                  'Construtora Vale Verde — Sr. Marcos', 'Arq. Helena Duarte',
                  'Loja Casa & Cia — Sr. Eduardo'];

const cidadesIN = ['São Paulo', 'Taboão da Serra', 'Osasco', 'Cotia', 'Barueri', 'Embu das Artes', 'Carapicuíba'];
const cidadesAMBIGUAS = ['Monte Alegre', 'São José', 'Santa Rita', 'Jardim América'];
const cidadesFORA = ['Manaus', 'Salvador', 'Fortaleza', 'Belém', 'Porto Alegre'];

const projetosB2C = [
  'cozinha planejada para apartamento de 70m²',
  'closet do casal e quarto do bebê',
  'sala completa: estante, painel TV e rack',
  'home office + dormitório de filha adolescente',
  'cozinha + área gourmet integrada',
  'banheiro com gabinete planejado e nichos'
];
const projetosB2B = [
  'apartamento de cliente alto padrão — todos os ambientes',
  'lançamento de 12 unidades, decorado',
  '3 lojas conceito em shopping',
  'sala comercial de coworking, marcenaria modular',
  'cobertura duplex, projeto autoral',
  'showroom de revenda — 4 ambientes'
];

const orcamentosB2C = ['R$ 18 mil', 'R$ 35 mil', 'R$ 60 mil', 'R$ 90 mil', 'ainda não sei'];
const orcamentosB2B = ['R$ 150 mil por unidade', 'R$ 250 mil', 'R$ 400 mil', 'a definir conforme briefing'];

let cidade;
if (perfil === 'fora_cobertura') {
  cidade = pick([...cidadesFORA, ...cidadesAMBIGUAS]);
} else {
  cidade = pick([...cidadesIN, ...cidadesIN, ...cidadesAMBIGUAS]); // viés p/ cobertura
}

const persona = {
  nome: audiencia === 'b2b' ? pick(nomesB2B) : pick(nomesB2C),
  audiencia,
  perfil,
  cidade,
  projeto: audiencia === 'b2b' ? pick(projetosB2B) : pick(projetosB2C),
  orcamento: audiencia === 'b2b' ? pick(orcamentosB2B) : pick(orcamentosB2C),
  urgencia: pick(['nenhuma — só pesquisando', 'média — quero fechar em 30 dias',
                  'alta — preciso entregar em 2 semanas', 'baixa — obra começa em 4 meses']),
  email: 'simulador+' + cfg.sim_id.toLowerCase() + '@aiagent.test'
};

// Cenário e objetivo do "treino"
const cenarios = {
  facil: 'Cliente colaborativo: responde rápido, dá informações sem resistência, aceita primeira sugestão de horário.',
  dificil: 'Cliente cético: pede desconto antes de qualificar, questiona preço, compara com concorrentes, tenta empurrar horário fora da grade.',
  confuso: 'Cliente desorganizado: muda de ideia, mistura informações, pergunta sobre coisas off-topic (entrega, garantia, montagem), responde apenas parcialmente.',
  fora_cobertura: 'Cliente em cidade ambígua ou claramente fora da área. Quer testar se a Joanna desambigua ("Monte Alegre? Em qual estado?") em vez de rejeitar direto.'
};

const objetivos = {
  facil: 'Verificar se a Joanna conduz o funil normal: qualificação → agendamento → confirmação. Deve concluir agendamento.',
  dificil: 'Verificar se a Joanna sustenta preço, qualifica antes de propor, e não promete desconto sem aprovação.',
  confuso: 'Verificar se a Joanna mantém o foco, reconduz a conversa pro funil, e não trava com informação parcial.',
  fora_cobertura: 'Verificar se a Joanna usa a lógica de 3 estados (IN/UNKNOWN/AMBIGUOUS) e pede UF/estado em vez de rejeitar.'
};

return [{ json: {
  ...cfg,
  audiencia,
  perfil,
  persona,
  cenario: cenarios[perfil],
  objetivo: objetivos[perfil],
  pushName: persona.nome,
  // chave de memória do agente simulador (separada por simulação)
  sim_memory_key: 'sim_mem:' + cfg.sim_id
}}];

// Inicializa o array de turnos para o SplitInBatches
const data = $input.first().json;
const max = Math.max(1, Math.min(30, Number(data.max_turnos) || 12));

const turnos = [];
for (let i = 1; i <= max; i++) {
  turnos.push({
    turno_num: i,
    is_first: i === 1,
    // payload da config copiado em cada item pra ficar acessível no loop
    sim_id: data.sim_id,
    sim_memory_key: data.sim_memory_key,
    telefone_sim: data.telefone_sim,
    pushName: data.pushName,
    audiencia: data.audiencia,
    perfil: data.perfil,
    persona: data.persona,
    cenario: data.cenario,
    objetivo: data.objetivo,
    joanna_webhook_url: data.joanna_webhook_url,
    wait_resposta_segundos: data.wait_resposta_segundos,
    max_turnos: max,
    sim_started_at: data.sim_started_at
  });
}

return turnos.map(t => ({ json: t }));

// Compila o relatório da simulação
const turnoData = $input.first().json;
const sd = $getWorkflowStaticData('node');
const sim_id = turnoData.sim_id;

const estado = (sd.simulacoes && sd.simulacoes[sim_id]) || {
  conversa: [], finalizado: false, resultado: 'timeout', turnos_executados: 0, observacoes: ''
};

const resultado = estado.finalizado ? estado.resultado : 'timeout_max_turnos';

return [{ json: {
  sim_id,
  telefone_sim: turnoData.telefone_sim,
  audiencia: turnoData.audiencia,
  persona: turnoData.persona,
  cenario: turnoData.cenario,
  objetivo: turnoData.objetivo,
  conversa: estado.conversa,
  total_turnos: estado.turnos_executados,
  resultado,
  observacoes: estado.observacoes || '',
  sim_started_at: turnoData.sim_started_at,
  sim_finished_at: new Date().toISOString()
}}];

// Em cada iteração:
// 1. Lê estado da simulação do staticData
// 2. Se já finalizou, gera flag pra pular (IF vai bloquear)
// 3. Caso contrário, monta o contexto pro agente simulador

const turno = $input.first().json;
const sim_id = turno.sim_id;
const sd = $getWorkflowStaticData('node');

if (!sd.simulacoes) sd.simulacoes = {};
if (!sd.simulacoes[sim_id]) {
  sd.simulacoes[sim_id] = {
    conversa: [],
    finalizado: false,
    resultado: null,
    turnos_executados: 0,
    observacoes: '',
    last_msg_id_joanna: 0
  };
}

const estado = sd.simulacoes[sim_id];

// Monta transcript em texto pra o prompt
const transcript_text = estado.conversa.map(t => {
  if (t.de === 'cliente') return `[Você disse no turno ${t.turno}] ${t.texto}`;
  return `[Joanna respondeu no turno ${t.turno}] ${t.texto}`;
}).join('\n');

return [{
  json: {
    ...turno,
    finalizado: estado.finalizado,
    turnos_executados: estado.turnos_executados,
    transcript_text: transcript_text || '(início da conversa)',
    ultima_msg_joanna: estado.conversa.filter(t => t.de === 'joanna').slice(-1)[0]?.texto || '(ainda não respondeu)',
    last_msg_id_joanna: estado.last_msg_id_joanna || 0
  }
}];

