// Constrói payload no formato Evolution API que o webhook da Joanna espera
const turno = $('Code: Preparar Turno').first().json;
const agentOut = $input.first().json;

// O output do Agent vem em .output (string)
let mensagem = (agentOut.output || agentOut.text || '').trim();

// Detecta tag de fim e remove do texto antes de enviar
let tagFim = null;
const fimRegex = /\[\[FIM:(AGENDADO|DESISTIU|FORA_COBERTURA)\]\]/;
const m = mensagem.match(fimRegex);
if (m) {
  tagFim = m[1].toLowerCase();
  mensagem = mensagem.replace(fimRegex, '').trim();
}

// Garante mensagem não-vazia
if (!mensagem) mensagem = '(...)';

const telefone = turno.telefone_sim;
const remoteJid = telefone + '@s.whatsapp.net';
const messageId = 'SIMMSG_' + Date.now() + '_' + Math.floor(Math.random()*10000);

// Payload Evolution API (webhook event: messages.upsert)
const payload = {
  event: 'messages.upsert',
  instance: 'AiAgentAutomate',
  data: {
    key: {
      remoteJid,
      fromMe: false,
      id: messageId
    },
    pushName: turno.pushName,
    message: {
      conversation: mensagem
    },
    messageType: 'conversation',
    messageTimestamp: Math.floor(Date.now() / 1000)
  }
};

return [{
  json: {
    ...turno,
    payload,
    mensagem_cliente: mensagem,
    tag_fim: tagFim
  }
}];

// Atualiza o staticData da simulação com:
// - mensagem do cliente do turno atual
// - resposta(s) consolidada(s) da Joanna
// - detecta condições de fim (tag do cliente OU keywords da Joanna)

const payloadNode = $('Code: Build Payload Evolution').first().json;
const turnoNode = $('Code: Preparar Turno').first().json;
const respostas = $input.all().map(i => i.json);

const sim_id = payloadNode.sim_id;
const sd = $getWorkflowStaticData('node');
const estado = sd.simulacoes[sim_id];

// Ordena por id asc (mais antigas primeiro)
respostas.sort((a, b) => (a.id || 0) - (b.id || 0));

const respostasNovas = respostas.filter(r => r.id > (estado.last_msg_id_joanna || 0));

// Salva último id processado
if (respostasNovas.length > 0) {
  estado.last_msg_id_joanna = respostasNovas[respostasNovas.length - 1].id;
}

const respostaConsolidada = respostasNovas.map(r => r.conteudo).join(' | ') || '(sem resposta — timeout)';

const turnoAtual = turnoNode.turno_num;
estado.turnos_executados = turnoAtual;

// Append do turno do cliente
estado.conversa.push({
  turno: turnoAtual,
  de: 'cliente',
  texto: payloadNode.mensagem_cliente,
  ts: new Date().toISOString()
});

// Append da resposta da Joanna (se houve)
if (respostasNovas.length > 0) {
  estado.conversa.push({
    turno: turnoAtual,
    de: 'joanna',
    texto: respostaConsolidada,
    segmentos: respostasNovas.length,
    ts: new Date().toISOString()
  });
}

// === Detecção de fim ===
let finalizou = false;
let resultado = null;
let obs = [];

// 1. Tag explícita do cliente
if (payloadNode.tag_fim) {
  finalizou = true;
  if (payloadNode.tag_fim === 'agendado') resultado = 'agendou';
  else if (payloadNode.tag_fim === 'desistiu') resultado = 'desistiu';
  else if (payloadNode.tag_fim === 'fora_cobertura') resultado = 'fora_cobertura_detectado';
  obs.push('Tag de fim no turno ' + turnoAtual + ': ' + payloadNode.tag_fim);
}

// 2. Joanna sem resposta (provável erro/pausa)
if (!finalizou && respostasNovas.length === 0) {
  // Tolera 1 turno sem resposta, fecha no 2º
  estado.turnos_sem_resposta = (estado.turnos_sem_resposta || 0) + 1;
  if (estado.turnos_sem_resposta >= 2) {
    finalizou = true;
    resultado = 'joanna_sem_resposta';
    obs.push('Joanna não respondeu por 2 turnos consecutivos.');
  }
} else {
  estado.turnos_sem_resposta = 0;
}

// 3. Joanna sinalizou agendamento confirmado (heurísticas)
if (!finalizou && respostasNovas.length > 0) {
  const texto = respostaConsolidada.toLowerCase();
  const sinaisAgendamento = ['confirmada', 'agendada', 'reunião marcada',
                             'reuniao marcada', 'reservei sua', 'até lá',
                             'até nossa reunião', 'até nossa reuniao'];
  if (sinaisAgendamento.some(s => texto.includes(s))) {
    // Confirmação forte se também menciona horário/data + canal
    const temData = /(\d{1,2}[\/\-]\d{1,2}|\d{1,2}h|\d{1,2}:\d{2}|amanhã|amanha|segunda|terça|terca|quarta|quinta|sexta|sábado|sabado|domingo)/i.test(texto);
    if (temData) {
      finalizou = true;
      resultado = 'agendou';
      obs.push('Joanna confirmou agendamento (heurística texto).');
    }
  }
  // Joanna sinalizou fora de cobertura
  if (texto.includes('não atendemos') || texto.includes('nao atendemos') ||
      texto.includes('fora da nossa área') || texto.includes('fora da nossa area')) {
    finalizou = true;
    resultado = 'fora_cobertura_joanna';
    obs.push('Joanna sinalizou fora de cobertura.');
  }
}

// 4. Atingiu máx
if (!finalizou && turnoAtual >= turnoNode.max_turnos) {
  finalizou = true;
  resultado = 'timeout_max_turnos';
  obs.push('Atingiu o máximo de ' + turnoNode.max_turnos + ' turnos.');
}

if (finalizou) {
  estado.finalizado = true;
  estado.resultado = resultado;
}
estado.observacoes = (estado.observacoes ? estado.observacoes + ' | ' : '') + obs.join(' | ');

return [{
  json: {
    sim_id,
    turno: turnoAtual,
    mensagem_cliente: payloadNode.mensagem_cliente,
    resposta_joanna: respostaConsolidada,
    finalizado: finalizou,
    resultado,
    obs: obs.join(' | ')
  }
}];
